}

void collect(TreeNode* node, int sum, vector<int>& sums) {
    if (node == nullptr) return;
    sum += node->val;
    if (!node->left && !node->right) sums.push_back(sum);   // every root-to-leaf sum
    collect(node->left, sum, sums);
    collect(node->right, sum, sums);
}

bool hasPathSum(TreeNode* root, int targetSum) {
