    dfs(root, target, new ArrayList<>(), result);
    return result;
}

void dfs(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> result) {
    if (node == null) return;
    path.add(node.val);
    remaining -= node.val;
    if (node.left == null && node.right == null && remaining == 0) {
        result.add(new ArrayList<>(path));  // a leaf that uses up the target exactly
    }
    dfs(node.left, remaining, path, result);
    dfs(node.right, remaining, path, result);
    path.remove(path.size() - 1);           // backtrack
}

void dfs(TreeNode* node, int remaining, vector<int>& path, vector<vector<int>>& result) {
    if (node == nullptr) return;
    path.push_back(node->val);
    remaining -= node->val;
    if (!node->left && !node->right && remaining == 0) {
        result.push_back(path);             // a leaf that uses up the target exactly (a copy)
    }
    dfs(node->left, remaining, path, result);
    dfs(node->right, remaining, path, result);
    path.pop_back();                        // backtrack
}

