function countPathSums(root, target) {
  const seen = new Map([[0, 1]]);          // prefix sum -> times seen on the current path
  let count = 0;
  function dfs(node, sum) {
    if (node === null) return;
    sum += node.val;                        // root-to-here sum
    count += seen.get(sum - target) ?? 0;   // paths ending here that add up to target
    seen.set(sum, (seen.get(sum) ?? 0) + 1);
    dfs(node.left, sum);
    dfs(node.right, sum);
    seen.set(sum, seen.get(sum) - 1);       // leaving: this prefix is off the path
  }
  dfs(root, 0);
  return count;
}

private int count;

public int countPathSums(TreeNode root, int target) {
    Map<Long, Integer> seen = new HashMap<>();    // prefix sum -> times seen on the current path
    seen.put(0L, 1);
    count = 0;
    dfs(root, 0L, target, seen);
    return count;
}

void dfs(TreeNode node, long sum, int target, Map<Long, Integer> seen) {
    if (node == null) return;
    sum += node.val;                              // root-to-here sum (long: sums can overflow int)
    count += seen.getOrDefault(sum - target, 0);  // paths ending here that add up to target
    seen.merge(sum, 1, Integer::sum);
    dfs(node.left, sum, target, seen);
    dfs(node.right, sum, target, seen);
    seen.merge(sum, -1, Integer::sum);            // leaving: this prefix is off the path
}

void dfs(TreeNode* node, long long sum, int target, unordered_map<long long, int>& seen, int& count) {
    if (node == nullptr) return;
    sum += node->val;                       // root-to-here sum (long long: sums can overflow int)
    auto it = seen.find(sum - target);
    if (it != seen.end()) count += it->second;   // paths ending here that add up to target
    seen[sum]++;
    dfs(node->left, sum, target, seen, count);
    dfs(node->right, sum, target, seen, count);
    seen[sum]--;                            // leaving: this prefix is off the path
}

